import React, { Component } from "react";

export default class Aboutus extends Component {
    render() {
        return (
            <div>
                <a className="title">TaiLink</a>
                <a className="content">TaiLink helps locate lost or stolen pets through the use of a microchip implanted in them.
                    Our website has many feature:</a>
                <a className="content">1.allowing those who found the pets to conversate with the owners.</a> 
                <a className="content"> 2.Enabling them to provide updates via the chip's identification number.</a> 
                <a className="content">3.Users can also post information about lost pets that have not yet been found or animals in need of assistance</a> 
                <a className="content">4.Suggestions for veterinary services or suitable homes can also be provided.
                    </a>
            </div>
        );
    }
}
